const items = $input.all();

return items.map((item, index) => {
  const output = item.json.output?.[0] || {};
  const content0 = output.content?.[0] || {};
  const raw = content0.text || '{}';

  let parsed;
  try {
    parsed = JSON.parse(raw);
  } catch (error) {
    parsed = { verdict: null };
  }

  const verdict =
    typeof parsed.verdict === 'string'
      ? parsed.verdict.toLowerCase() === 'true'
      : parsed.verdict;

  return {
    json: {
      index,
      message: {
        role: output.role || 'assistant',
        content: {
          verdict: verdict
        },
        refusal: null,
        annotations: content0.annotations || [],
        logprobs: content0.logprobs || null,
        finish_reason: output.status === 'completed' ? 'stop' : output.status
      }
    }
  };
});

